entries[147804] = { ["name"] = "Wilder Traumläufer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren wilden Traumläufer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Legionsrichter\" verfügbar.\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\nVerkaufspreis:\n\"Traumläufer flitzen nach Belieben zwischen dieser Welt und dem Smaragdgrünen Traum hin und her und leben ihre wilde Natur aus.\"\nBeute von:\nKiste der Traumweber" }
entries[147805] = { ["name"] = "Sturmschwinge der Valarjar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört Eure Sturmschwinge der Valarjar oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Legionsrichter\" verfügbar.\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\nVerkaufspreis:\n\"Wenn sie mit den Flügeln schlägt, klingt es wie weit entfernter, grollender Donner.\"\nBeute von:\nSchließkassette der Valarjar" }
entries[147806] = { ["name"] = "Wolkenschwingenhippogryph", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Wolkenschwingenhippogryphen oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Legionsrichter\" verfügbar.\nVerkaufspreis:\n\"Die Wolkenschwingen von Azsuna bevorzugen es mehr noch als normale Hippogryphen, in hohen Berghöhlen weit über der Wolkengrenze ihre Nester zu bauen.\"\nBeute von:\nKiste von Farondis" }
entries[147807] = { ["name"] = "Hochbergurhorn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euer Hochbergurhorn oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Legionsrichter\" verfügbar.\nVerkaufspreis:\n\"Das Reittier der Wahl bei den Jägern des Hochbergs. Kann mühelos über die reißenden Flüsse des Kieferfelsbeckens springen, selbst wenn ein ausgewachsener Tauren darauf reitet.\"\nBeute von:\nHochbergvorräte" }
