entries[147864] = { ["name"] = "Banner der Legionsrichter", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert ein Banner der Legionsrichter auf dem Boden. Auf den Verheerten Inseln verringert es den erlittenen Schaden von Spielercharakteren innerhalb von 30 Metern um 5%. (1 Stunde Abklingzeit)\nBenötigt Die Legionsrichter\n- Wohlwollend\nVerkaufspreis:" }
entries[147867] = { ["name"] = "Gestohlener Feger", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Platziert Euren gestohlenen Feger auf dem Boden. Er hat sehr wenig Energie und wird nicht lange durchhalten. (5 Min Abklingzeit)\nMit der Veröffentlichung von \"Legion Remix: Legionsrichter\" verfügbar.\n\"Die Wyrmzungen auf Suramars goldene Straßen loszulassen war nicht die beste Idee. Sie selbst fanden es allerdings großartig.\"\nVerkaufspreis:" }
entries[147868] = { ["name"] = "Elixier des unerreichten Dämonentötens", ["text"] = "Benutzen: Erhöht Eure Angriffskraft gegen Dämonen um 200. Kann nur im Freien auf den Verheerten Inseln verwendet werden und hält 15 Min. lang an. Kampfelixier. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[147869] = { ["name"] = "Teufelsmeteorit", ["text"] = "Benutzen: Schleudert den Benutzer als Teufelsmeteor weit weg. Kann nur auf den Verheerten Inseln verwendet werden.\n\"Möglicherweise ein Stück von einer Höllenbestie. Es ist immer noch warm.\"\nVerkaufspreis:" }
entries[147870] = { ["name"] = "Merkwürdiger Dimensionssplitter", ["text"] = "Benutzen: Teleportiert Euch unterschiedlich oft.\n\nKann nur auf den Verheerten Inseln und Argus verwendet werden. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[147871] = { ["name"] = "Verdammnisstein", ["text"] = "Benutzen: Beschwört einen Verdammnisstein. Wenn vier Opfer das Verdammnisritual ausführen, wird eines von ihnen nicht überleben. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
