entries[147901] = { ["name"] = "Leuchtender Sternensucher", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren leuchtenden Sternensucher oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die energiegeladenen Panthara von Argus spüren bei der Jagd die Energie in Lebewesen auf. Wenn sie sich einer starken Energiequelle nähern, ändern sie sichtlich ihre Farbe und werden aufgeregt.\"\nWoW-Shop" }
