entries[147906] = { ["name"] = "Teufelsherz von Argus", ["text"] = "Questgegenstand\n\"Das Teufelsherz von Argus war das Geheimnis hinter der Unsterblichkeit von Hochinquisitor Raalgar. Die Brunnen, die es mit Argus verbanden, wurden zwar vernichtet, doch schützt es auf Argus immer noch jene, die magisch mit ihm in Verbindung stehen.\"" }
entries[147907] = { ["name"] = "Herzförmige Schachtel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Liebe liegt in der Luft\n\"Enthält Zeichen der Liebe und eine Chance auf andere Preise. Bei der ersten Schachtel, die Eure Kriegsmeute an einem Tag verdient, besteht eine zusätzliche Chance auf seltene Belohnungen.\"\n<Zum Öffnen rechtsklicken>" }
